    ('events', 'yarl-dreamin-25', 0, true, $json${"recap":[],"cover":null,"gallery":[],"url":null,"credentialIds":[],"slug":"yarl-dreamin-25","title":"Yarl Dreamin’ 25","type":"conference","organiser":null,"location":"Jaffna","date":null,"description":"I joined the Salesforce community in Jaffna for sessions on Agentforce, Apex trigger frameworks, data quality, and real-time integrations. I also had the chance to meet fellow Trailblazers and exchange ideas about how they use Salesforce in their work."}$json$::jsonb),
